nguage_code\":\"zu\",\"enabled\":false,\"url_path\":\"/zu/\"}],\"breadcrumb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/2/\",\"title\":\"Chapter Two: Contents of the Gītā Summarized\"}],\"url_path\":\"/en/library/bg/2/51/\",\"bb\":738,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/2/50/\",\"title\":\"TEXT 50\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/2/52/\",\"title\":\"TEXT 52\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":822,\"bb\":567974,\"url_path\":\"/en/library/bg/2/51/devanagari/\",\"body_final\":\"कर्मजं बुद्धियुक्ता हि फलं त्यक्त्वा मनीषिणः ।
जन्मबन्धविनिर्मुक्ताः पदं गच्छन्त्यनामयम् ॥ ५१ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":823,\"bb\":739,\"url_path\":\"/en/library/bg/2/51/b739/\",\"body_value\":\"karma-jaṁ buddhi-yuktā hi
phalaṁ tyaktvā manīṣiṇaḥ
janma-bandha-vinirmuktāḥ
padaṁ gacchanty anāmayam\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":824,\"bb\":740,\"url_path\":\"/en/library/bg/2/51/b740/\",\"shadow_value\":\"karma-jam – due to fruitive activities; buddhi-yuktāḥ – being engaged in devotional service; hi – certainly; phalam – results; tyaktvā – giving up; manīṣiṇaḥ – great sages or devotees; janma-bandha – from the bondage of birth and death; vinirmuktāḥ – liberated; padam – position; gacchanti – they reach; anāmayam – without miseries.\",\"word_for_word_value\":[{\"word\":\"karma-jam\",\"translation\":\"due to fruitive activities\"},{\"word\":\"buddhi-yuktāḥ\",\"translation\":\"being engaged in devotional service\"},{\"word\":\"hi\",\"translation\":\"certainly\"},{\"word\":\"phalam\",\"translation\":\"results\"},{\"word\":\"tyaktvā\",\"translation\":\"giving up\"},{\"word\":\"manīṣiṇaḥ\",\"translation\":\"great sages or devotees\"},{\"word\":\"janma-bandha\",\"translation\":\"from the bondage of birth and death\"},{\"word\":\"vinirmuktāḥ\",\"translation\":\"liberated\"},{\"word\":\"padam\",\"translation\":\"position\"},{\"word\":\"gacchanti\",\"translation\":\"they reach\"},{\"word\":\"anāmayam\",\"translation\":\"without miseries\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":825,\"bb\":741,\"url_path\":\"/en/library/bg/2/51/b741/\",\"body_value\":\"By thus engaging in devotional service to the Lord, great sages or devotees free themselves from the results of work in the material world. In this way they become free from the cycle of birth and death and attain the state beyond all miseries [by going back to Godhead].\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":826,\"bb\":742,\"url_path\":\"/en/library/bg/2/51/b742/\",\"body_value\":\"The liberated living entities belong to that place where there are no material miseries. The Bhāgavatam (10.14.58) says:\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":827,\"bb\":743,\"url_path\":\"/en/library/bg/2/51/b743/\",\"body_value\":\"samāṣritā ye pada-pallava-plavaṁ
